import{_ as a,o as r,c as o,a2 as i}from"./chunks/framework.BXzK3EA4.js";const n="/assets/image%20(109).BENI53r1.png",t="/assets/groww1.CJGI7pC-.png",s="/assets/image%20(148).CyQvbLZz.png",k=JSON.parse('{"title":"Groww","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/groww.md","filePath":"connect-brokers/brokers/groww.md"}'),l={name:"connect-brokers/brokers/groww.md"};function d(c,e,g,p,h,u){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="groww" tabindex="-1">Groww <a class="header-anchor" href="#groww" aria-label="Permalink to &quot;Groww&quot;">​</a></h1><p>Groww is currently the #1 stockbroker in India by active clients, offering a seamless digital investing experience to millions of retail investors. With its recent launch of trading APIs, Groww has opened the door for developers and fintech platforms to integrate custom trading workflows. In the context of Tradeboard integration, Groww’s trading APIs provide capabilities for automated order placement, real-time market data access, and custom strategy execution for retail traders.</p><h3 id="how-to-get-groww-api-key-and-secret" tabindex="-1">How to Get Groww API Key and Secret? <a class="header-anchor" href="#how-to-get-groww-api-key-and-secret" aria-label="Permalink to &quot;How to Get Groww API Key and Secret?&quot;">​</a></h3><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><p>To integrate Tradeboard with Groww, follow the steps below to generate your API key (access token):</p><ol><li>Visit the <a href="https://groww.in/trade-api" target="_blank" rel="noreferrer">Groww Trade API Portal</a> and click on <strong>Getting Started</strong>.</li><li>Login using your Groww account credentials.</li><li>Click the <strong>Generate API Token</strong> button to create APIKey and APISecret</li></ol><figure><img src="'+t+'" alt=""><figcaption></figcaption></figure><p>Click on the <strong>Generate API Keys</strong> ,Enter the Token Name as &quot;Tradeboard&quot; or any name of your choice and press <strong>continue</strong></p><h4 id="now-generate-the-generated-grow-api-key-and-api-secret-from-the-generate-api-key" tabindex="-1">Now Generate the generated Grow API Key and API Secret from the Generate API Key <a class="header-anchor" href="#now-generate-the-generated-grow-api-key-and-api-secret-from-the-generate-api-key" aria-label="Permalink to &quot;Now Generate the generated Grow API Key and API Secret from the Generate API Key&quot;">​</a></h4><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><p>Click &quot;<strong>Add/Update Static IP</strong>&quot; next to Generate API Key</p><figure><img src="'+t+`" alt=""><figcaption></figcaption></figure><h3 id="important-points" tabindex="-1">Important Points <a class="header-anchor" href="#important-points" aria-label="Permalink to &quot;Important Points&quot;">​</a></h3><ul><li>Do <strong>not share</strong> your access token with untrusted third-party platforms or individuals.</li></ul><h4 id="configuration" tabindex="-1">Configuration: <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration:&quot;">​</a></h4><p>Here is how you would typically set up your environment variables in a .env file for Groww&#39;s API:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BROKER_API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;your_groww_apikey_here&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BROKER_API_SECRET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;your_groww_apisecret_here&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">REDIRECT_URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;http://127.0.0.1:5000/groww/callback&#39;</span></span></code></pre></div><p>Integrating Tradeboard with Groww&#39;s trading API allows retail traders to leverage India’s most popular stockbroking platform for building and deploying their own algorithmic trading strategies. It’s a powerful combination for automating trading decisions while using a broker trusted by millions. As with any integration, be sure to handle token management carefully, log errors effectively, and build retry mechanisms to handle token expiry and downtime.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/groww/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,21)])])}const f=a(l,[["render",d]]);export{k as __pageData,f as default};
